public class PcodeVarargsExpression : it.unive.lisa.program.cfg.statement.NaryExpression {

	public PcodeVarargsExpression(CFG cfg, 
			VarargsExprContext ctx, 
			Expression[] exps) : base(cfg, ctx.location(), ctx.mnemonic(), cfg.getDescriptor().getUnit().getProgram().getTypes().getIntegerType(), exps)
    {
	}

	/* @Override */
