			Statement o) {
		return 0; // no extra fields to compare
	}

	public AnalysisState<A> fwdBinarySemantics<A>/* where A : AbstractState<A> */(
			InterproceduralAnalysis<A> interprocedural,
			AnalysisState<A> state,
			SymbolicExpression left,
			SymbolicExpression right,
			StatementStore<A> expressions)
    {

		return state.smallStepSemantics(
			new BinaryExpression(
				getStaticType(),
				left,
				right,
				LogicalOr.INSTANCE,
				getLocation()),
			this);
	}

	/* @Override */
	public AnalysisState<A> forwardSemanticsAux<A>/* where A : AbstractState<A> */(
			InterproceduralAnalysis<A> interprocedural,
			AnalysisState<A> state,
			ExpressionSet[] @params,
			StatementStore<A> expressions)
    {
		AnalysisState<A> result = state.bottom();
		foreach (SymbolicExpression expBase in @params[0]) {
			for (int i = 1; i < @params.length; i++) {
				foreach (SymbolicExpression exp in @params[i]) {
					//result = result.lub(state.smallStepSemantics(exp, this));
					result = result.lub(
						fwdBinarySemantics(interprocedural, state, expBase, exp, expressions));
				}
			}
		}
		return result;
	}
	
